package run.ikaros.notes; import jakarta.validation.Valid; import java.time.Instant; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/private-notes") public class PrivateNoteRevisionController{private final PrivateNoteRevisionService service;public PrivateNoteRevisionController(PrivateNoteRevisionService s){service=s;}@PostMapping("/notes/{noteId}/revisions")public Mono<NoteRevisionView> commit(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID noteId,@Valid@RequestBody CommitNoteRevisionRequest r){return service.commit(a,noteId,r);}@GetMapping("/notes/{noteId}/revisions")public Flux<NoteRevisionView> history(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID noteId){return service.history(a,noteId);}@GetMapping("/vaults/{vaultId}/sync")public Mono<PrivateNoteSyncView> sync(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@RequestParam(required=false)Instant cursor){return service.sync(a,vaultId,cursor);}}
